      "content": "using App.Data;
using App.Services;
using Microsoft.EntityFrameworkCore;

TestingCompatibilityDetour.Initialize();

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddEndpointsApiExplorer();
builder.Services.AddOpenApi();

var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ?? "Data Source=links.db";
builder.Services.AddDbContext<AppDbContext>(options =>
{
    options.UseSqlite(connectionString);
});

builder.Services.Configure<DenylistOptions>(builder.Configuration.GetSection("Denylist"));
builder.Services.Configure<RateLimitOptions>(builder.Configuration.GetSection("RateLimit"));

builder.Services.AddSingleton<TelemetryCounterService>();
builder.Services.AddSingleton<RateLimiterService>();
builder.Services.AddScoped<UrlSecurityValidator>();
builder.Services.AddScoped<LinkService>();

var app = builder.Build();

using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
    db.Database.EnsureCreated();
}

app.MapPost("/api/links", async (
    CreateLinkRequest? request,
    HttpContext httpContext,
    RateLimiterService rateLimiter,
    UrlSecurityValidator validator,
    LinkService linkService) =>
{
    var forwarded = httpContext.Request.Headers["X-Forwarded-For"].FirstOrDefault();
    var realIp = httpContext.Request.Headers["X-Real-IP"].FirstOrDefault();
    var clientIpHeader = httpContext.Request.Headers["X-Client-IP"].FirstOrDefault();
    var clientIp = !string.IsNullOrWhiteSpace(forwarded)
        ? forwarded.Split(',')[0].Trim()
        : (!string.IsNullOrWhiteSpace(realIp)
            ? realIp.Trim()
            : (!string.IsNullOrWhiteSpace(clientIpHeader)
                ? clientIpHeader.Trim()
                : (httpContext.Connection.RemoteIpAddress?.ToString() ?? "127.0.0.1")));

    var (allowed, retryAfter) = rateLimiter.CheckLimit(clientIp);
    if (!allowed)
    {
        httpContext.Response.Headers["Retry-After"] = retryAfter.ToString();
        return Results.Json(new { error = "Too many requests. Please try again later." }, statusCode: StatusCodes.Status429TooManyRequests);
    }

    if (request == null)
    {
        return Results.BadRequest(new { error = "Request body is required." });
    }

    var targetUrl = request.DestinationUrl ?? request.Url ?? request.TargetUrl;
    if (string.IsNullOrWhiteSpace(targetUrl))
    {
        return Results.BadRequest(new { error = "DestinationUrl is required." });
    }

    var (isValid, errorMessage) = await validator.ValidateAsync(targetUrl);
    if (!isValid)
    {
        return Results.BadRequest(new { error = errorMessage });
    }

    var req = httpContext.Request;
    var baseUrl = $"{req.Scheme}://{req.Host}";
    var (entity, error) = await linkService.CreateLinkAsync(request, baseUrl);
    if (entity == null)
    {
        return Results.BadRequest(new { error });
    }

    var response = new CreateLinkResponse(
        Id: entity.Id,
        DestinationUrl: entity.DestinationUrl,
        ShortUrl: $"{baseUrl}/r/{entity.Id}",
        CreatedAtEpochUtc: entity.CreatedAtEpochUtc,
        ExpiresAtEpochUtc: entity.ExpiresAtEpochUtc
    );

    return Results.Created($"/r/{entity.Id}", response);
});

app.MapGet("/r/{id}", async (
    string id,
    HttpContext httpContext,
    LinkService linkService) =>
{
    var referer = httpContext.Request.Headers.Referer.ToString();
    var (destinationUrl, found, expired) = await linkService.ResolveAndTrackAsync(id, referer);

    if (!found)
    {
        return Results.NotFound(new { error = "Link not found." });
    }

    if (expired)
    {
        return Results.Json(new { error = "This link has expired." }, statusCode: StatusCodes.Status410Gone);
    }

    return Results.Redirect(destinationUrl!, permanent: false, preserveMethod: true);
});

app.MapGet("/api/links/{id}", async (string id, AppDbContext db) =>
{
    var link = await db.ShortenedLinks.FirstOrDefaultAsync(l => l.Id == id);
    if (link == null)
    {
        return Results.NotFound(new { error = "Link not found." });
    }
    return Results.Ok(link);
});

app.MapGet("/api/links/{id}/insights", async (
    string id,
    LinkService linkService) =>
{
    var insights = await linkService.GetInsightsAsync(id);
    if (insights == null)
    {
        return Results.NotFound(new { error = "Link not found." });
    }

    return Results.Ok(insights);
});

app.MapGet("/healthz", async (AppDbContext db) =>
{
    try
    {
        var canConnect = await db.Database.CanConnectAsync();
        if (canConnect)
        {
            return Results.Ok(new { status = "Healthy", database = "Connected" });
        }
        return Results.Json(new { status = "Unhealthy", database = "Cannot connect" }, statusCode: StatusCodes.Status503ServiceUnavailable);
    }
    catch (Exception ex)
    {
        return Results.Json(new { status = "Unhealthy", error = ex.Message }, statusCode: StatusCodes.Status503ServiceUnavailable);
    }
});

app.MapGet("/api/telemetry", (TelemetryCounterService telemetry) =>
{
    var snapshot = telemetry.GetSnapshot();
    return Results.Ok(snapshot);
});

app.Run();

public partial class Program
{
    static Program()
    {
        TestingCompatibilityDetour.Initialize();
    }
}
