public class TelemetryCounterService
{
    private long _ssrfRejections;
    private long _denylistBlocks;
    private long _unsupportedSchemeRejections;
    private long _rateLimitBlocks;
    private long _linksCreated;
    private long _redirectsResolved;

    public void IncrementSsrfRejections() => Interlocked.Increment(ref _ssrfRejections);
    public void IncrementDenylistBlocks() => Interlocked.Increment(ref _denylistBlocks);
    public void IncrementUnsupportedSchemeRejections() => Interlocked.Increment(ref _unsupportedSchemeRejections);
    public void IncrementRateLimitBlocks() => Interlocked.Increment(ref _rateLimitBlocks);
    public void IncrementLinksCreated() => Interlocked.Increment(ref _linksCreated);
    public void IncrementRedirectsResolved() => Interlocked.Increment(ref _redirectsResolved);

    public TelemetrySnapshot GetSnapshot()
    {
        return new TelemetrySnapshot(
            SsrfRejections: Interlocked.Read(ref _ssrfRejections),
            DenylistBlocks: Interlocked.Read(ref _denylistBlocks),
            UnsupportedSchemeRejections: Interlocked.Read(ref _unsupportedSchemeRejections),
            RateLimitBlocks: Interlocked.Read(ref _rateLimitBlocks),
            LinksCreated: Interlocked.Read(ref _linksCreated),
            RedirectsResolved: Interlocked.Read(ref _redirectsResolved)
        );
    }
}

public record TelemetrySnapshot(
    long SsrfRejections,
    long DenylistBlocks,
    long UnsupportedSchemeRejections,
    long RateLimitBlocks,
    long LinksCreated,
    long RedirectsResolved
)
{
    public long SsrfBlocks => SsrfRejections;
    public long DenylistRejections => DenylistBlocks;
    public long RateLimitRejections => RateLimitBlocks;
    public long TotalRedirects => RedirectsResolved;
    public long TotalLinksCreated => LinksCreated;
}
