namespace Microsoft.AspNetCore.Mvc.Testing
{
    public class WebApplicationClientOptions
    {
        public bool AllowAutoRedirect { get; set; } = true;
        public Uri BaseAddress { get; set; } = new Uri("http://localhost");
        public bool HandleCookies { get; set; } = true;
        public int MaxAutomaticRedirections { get; set; } = 7;
    }

    public static class WebApplicationClientOptionsExtensions
    {
        public static HttpClient CreateClient(this object factory, WebApplicationClientOptions options)
        {
            var factoryType = factory.GetType();

            var clientOptionsType = Type.GetType("Microsoft.AspNetCore.Mvc.Testing.WebApplicationFactoryClientOptions, Microsoft.AspNetCore.Mvc.Testing")
                ?? AppDomain.CurrentDomain.GetAssemblies()
                    .Select(a =>
                    {
                        try { return a.GetType("Microsoft.AspNetCore.Mvc.Testing.WebApplicationFactoryClientOptions"); } catch { return null; }
                    })
                    .FirstOrDefault(t => t != null)
                ?? AppDomain.CurrentDomain.GetAssemblies()
                    .SelectMany(a =>
                    {
                        try { return a.GetTypes(); } catch { return Array.Empty<Type>(); }
                    })
                    .FirstOrDefault(t => t.Name == "WebApplicationFactoryClientOptions");

            if (clientOptionsType != null)
            {
                var realOptions = Activator.CreateInstance(clientOptionsType)!;
                clientOptionsType.GetProperty("AllowAutoRedirect")?.SetValue(realOptions, options.AllowAutoRedirect);
                clientOptionsType.GetProperty("BaseAddress")?.SetValue(realOptions, options.BaseAddress);
                clientOptionsType.GetProperty("HandleCookies")?.SetValue(realOptions, options.HandleCookies);
                clientOptionsType.GetProperty("MaxAutomaticRedirections")?.SetValue(realOptions, options.MaxAutomaticRedirections);

                var method = factoryType.GetMethod("CreateClient", new[] { clientOptionsType });
                if (method != null)
                {
                    return (HttpClient)method.Invoke(factory, new[] { realOptions })!;
                }
            }

            var defaultMethod = factoryType.GetMethod("CreateClient", Type.EmptyTypes);
            if (defaultMethod != null)
            {
                return (HttpClient)defaultMethod.Invoke(factory, null)!;
            }

            throw new InvalidOperationException("Could not invoke CreateClient on factory.");
        }

        public static HttpClient CreateDefaultClient(this object factory, WebApplicationClientOptions options)
            => CreateClient(factory, options);
    }
}

