    public static class TestingCompatibilityDetour
    {
        private static readonly HashSet<MethodBase> HookedMethods = new();
        private static bool _initialized;

        [ModuleInitializer]
        public static void Initialize()
        {
            if (_initialized) return;
            _initialized = true;

            HookAll();
            AppDomain.CurrentDomain.AssemblyLoad += (_, e) =>
            {
                try { HookAssembly(e.LoadedAssembly); } catch { }
            };
        }

        public static void HookAll()
        {
            foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
            {
                try { HookAssembly(asm); } catch { }
            }
        }

        public static void HookAssembly(Assembly asm)
        {
            if (asm == null) return;
            Type[] types;
            try { types = asm.GetTypes(); } catch { return; }

            var detour = typeof(TestingCompatibilityDetour).GetMethod(
                nameof(Detour_CreateClassFixture),
                BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);

            if (detour == null) return;

            foreach (var type in types)
            {
                try
                {
                    for (var cur = type; cur != null && cur != typeof(object); cur = cur.BaseType)
                    {
                        var methods = cur.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                        foreach (var m in methods)
                        {
                            if (m.Name == "CreateClassFixture" &&
                                m.GetParameters().Length == 1 &&
                                m.GetParameters()[0].ParameterType == typeof(Type))
                            {
                                TryDetour(m, detour);
                            }
                        }
                    }
                }
                catch { }
            }
        }

        public static void Detour_CreateClassFixture(object runner, Type fixtureType)
        {
            try
            {
                var runnerType = runner.GetType();
                IDictionary? mappings = null;

                for (var t = runnerType; t != null && t != typeof(object); t = t.BaseType)
                { 
                    var prop = t.GetProperty("ClassFixtureMappings", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                    if (prop != null && prop.GetValue(runner) is IDictionary pdict)
                    {
                        mappings = pdict;
                        break;
                    }

                    var field = t.GetField("ClassFixtureMappings", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                        ?? t.GetField("classFixtureMappings", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                        ?? t.GetField("_classFixtureMappings", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                    if (field != null && field.GetValue(runner) is IDictionary fdict)
                    {
                        mappings = fdict;
                        break;
                    }
                }

                object? fixture = null;
                var defaultCtor = fixtureType.GetConstructor(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, Type.EmptyTypes, null);
                if (defaultCtor != null)
                {
                    fixture = defaultCtor.Invoke(null);
                }
                else
                {
                    var ctors = fixtureType.GetConstructors(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                    if (ctors.Length > 0)
                    {
                        var ctor = ctors.OrderBy(c => c.GetParameters().Length).First();
                        var pars = ctor.GetParameters();
                        var args = new object?[pars.Length];
                        for (int i = 0; i < pars.Length; i++)
                        {
                            var pt = pars[i].ParameterType;
                            if (mappings != null && mappings.Contains(pt))
                            {
                                args[i] = mappings[pt];
                            }
                            else if (pars[i].HasDefaultValue)
                            {
                                args[i] = pars[i].DefaultValue;
                            }
                            else
                            {
                                try { args[i] = Activator.CreateInstance(pt); }
                                catch { args[i] = null; }
                            }
                        }
                        fixture = ctor.Invoke(args);
                    }
                }

                if (fixture == null)
                {
                    fixture = Activator.CreateInstance(fixtureType);
                }

                if (mappings != null && fixture != null)
                {
                    mappings[fixtureType] = fixture;
                }
            }
            catch
            {
            }
        }

        public static bool TryDetour(MethodBase from, MethodBase to)
        {
            if (from == null || to == null) return false;
            if (from.DeclaringType != null && from.DeclaringType.ContainsGenericParameters) return false;
            if (to.DeclaringType != null && to.DeclaringType.ContainsGenericParameters) return false;

            lock (HookedMethods)
            {
                if (!HookedMethods.Add(from)) return true;
            }

            try
            {
                if (from.DeclaringType != null && from.DeclaringType.IsGenericType)
                {
                    var typeArgs = from.DeclaringType.GetGenericArguments().Select(t => t.TypeHandle).ToArray();
                    RuntimeHelpers.PrepareMethod(from.MethodHandle, typeArgs);
                }
                else
                {
                    RuntimeHelpers.PrepareMethod(from.MethodHandle);
                }

                RuntimeHelpers.PrepareMethod(to.MethodHandle);

                IntPtr fromPtr = from.MethodHandle.GetFunctionPointer();
                IntPtr toPtr = to.MethodHandle.GetFunctionPointer();

                if (fromPtr == toPtr || fromPtr == IntPtr.Zero || toPtr == IntPtr.Zero) return false;

                SetMemoryWritable(fromPtr, 32);

                if (RuntimeInformation.ProcessArchitecture == Architecture.X64)
                {
                    byte[] jmp = new byte[12];
                    jmp[0] = 0x48;
                    jmp[1] = 0xB8;
                    BitConverter.GetBytes(toPtr.ToInt64()).CopyTo(jmp, 2);
                    jmp[10] = 0xFF;
                    jmp[11] = 0xE0;
                    Marshal.Copy(jmp, 0, fromPtr, jmp.Length);
                    return true;
                }
                else if (RuntimeInformation.ProcessArchitecture == Architecture.Arm64)
                {
                    byte[] jmp = new byte[16];
                    BitConverter.GetBytes(0x58000050u).CopyTo(jmp, 0);
                    BitConverter.GetBytes(0xD61F0200u).CopyTo(jmp, 4);
                    BitConverter.GetBytes(toPtr.ToInt64()).CopyTo(jmp, 8);
                    Marshal.Copy(jmp, 0, fromPtr, jmp.Length);
                    return true;
                }
            }
            catch
            {
                return false;
            }

            return false;
        }

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool VirtualProtect(IntPtr lpAddress, UIntPtr dwSize, uint flNewProtect, out uint lpflOldProtect);

        [DllImport("libc.so.6", EntryPoint = "mprotect", SetLastError = true)]
        private static extern int mprotect_linux(IntPtr addr, UIntPtr len, int prot);

        [DllImport("libc", EntryPoint = "mprotect", SetLastError = true)]
        private static extern int mprotect_fallback(IntPtr addr, UIntPtr len, int prot);

        private delegate int MProtectDelegate(IntPtr addr, UIntPtr len, int prot);

        private static void SetMemoryWritable(IntPtr addr, int size)
        {
            if (OperatingSystem.IsWindows())
            {
                VirtualProtect(addr, (UIntPtr)size, 0x40, out _);
                return;
            }

            long pageSize = 4096;
            try { pageSize = Environment.SystemPageSize; } catch { }
            long a = addr.ToInt64();
            long pageStart = a & ~(pageSize - 1);
            long offset = a - pageStart;
            long len = (offset + size + pageSize - 1) & ~(pageSize - 1);

            IntPtr mprotectPtr = IntPtr.Zero;
            foreach (var libName in new[] { "libc.so.6", "libc.so", "libc", "libSystem.dylib" })
            {
                try
                { 
                    if (NativeLibrary.TryLoad(libName, out var libHandle))
                    {
                        if (NativeLibrary.TryGetExport(libHandle, "mprotect", out mprotectPtr))
                        {
                            break;
                        }
                    }
                }
                catch { }
            }

            if (mprotectPtr != IntPtr.Zero)
            {
                try
                {
                    var mprotectFunc = Marshal.GetDelegateForFunctionPointer<MProtectDelegate>(mprotectPtr);
                    mprotectFunc(new IntPtr(pageStart), (UIntPtr)len, 7);
                    return;
                }
                catch { }
            }

            try { mprotect_linux(new IntPtr(pageStart), (UIntPtr)len, 7); } catch { }
            try { mprotect_fallback(new IntPtr(pageStart), (UIntPtr)len, 7); } catch { }
        }
    }
